#!/usr/bin/env node
'use strict';

const { spawnSync } = require('child_process');

module.exports = port => {
  if (!port) {
    return {
      message: 'No port provided. Exiting...',
      error: true
    };
  }

  // Run `lsof -t -i:<port>` to get the PID(s)
  const lsof = spawnSync('lsof', ['-t', `-i:${port}`], { encoding: 'utf8', shell : false });

  if (lsof.error || lsof.status !== 0) {
    return {
      message: `Unable to find a process running on port ${port}`,
      error: true
    };
  }

  const pids = lsof.stdout.trim().split('\n').filter(Boolean);

  if (pids.length === 0) {
    return {
      message: `No process found running on port ${port}`,
      error: true
    };
  }

  try {
    for (const pid of pids) {
      const kill = spawnSync('kill', ['-9', pid]);
      if (kill.error || kill.status !== 0) {
        return {
          message: `Unable to kill process(es) ${pids.join(' ')}`,
          error: true
        };
      }
    }

    return {
      message: `Killed process(es) ${pids.join(' ')}`,
      error: false
    };
  } catch (err) {
    return {
      message: `Unexpected error while killing process(es) ${pids.join(' ')}`,
      error: true
    };
  }
};
